import { formatFileSize, validateFile, validateFileSize, validateFileType } from './utils';

describe('utils', () => {
  describe('validateFileType', () => {
    test.each`
      acceptedTypes   | fileType        | expected | when
      ${undefined}    | ${'text/plain'} | ${true}  | ${'no acceptedTypes are passed'}
      ${'text/plain'} | ${'text/plain'} | ${true}  | ${'file type matches acceptedTypes'}
      ${'image/jpeg'} | ${'text/plain'} | ${false} | ${'file type does not match acceptedTypes'}
      ${'.txt'}       | ${'text/plain'} | ${true}  | ${'file extension matches acceptedTypes'}
      ${'.jpg'}       | ${'text/plain'} | ${false} | ${'file extension does not match acceptedTypes'}
      ${'text/*'}     | ${'text/plain'} | ${true}  | ${'file type matches wildcard acceptedTypes'}
      ${'image/*'}    | ${'text/plain'} | ${false} | ${'file type does not match wildcard acceptedTypes'}
    `('should return $expected when $when', ({ acceptedTypes, fileType, expected }) => {
      const file = new File(['dummy content'], 'example.txt', { type: fileType });
      const result = validateFileType(file, acceptedTypes);
      expect(result).toBe(expected);
    });
  });
  describe('validateFileSize', () => {
    test.each`
      fileSize | maxSize | expected
      ${500}   | ${1000} | ${true}
      ${1500}  | ${1000} | ${false}
      ${1000}  | ${1000} | ${true}
      ${0}     | ${1000} | ${true}
    `(
      'should return $expected when file size is $fileSize and max size is $maxSize',
      ({ fileSize, maxSize, expected }) => {
        const file = new File(['a'.repeat(fileSize)], 'example.txt', { type: 'text/plain' });
        const result = validateFileSize(file, maxSize);
        expect(result).toBe(expected);
      }
    );
  });
  describe('validateFile', () => {
    it('should return an empty array when all validations pass', () => {
      const file = new File(['dummy content'], 'example.txt', { type: 'text/plain' });
      const validations = [
        { validation: () => true, errorMessage: 'Error message 1' },
        { validation: () => true, errorMessage: 'Error message 2' },
      ];
      const result = validateFile(file, validations);
      expect(result).toEqual([]);
    });

    it('should return an array with error messages when some validations fail', () => {
      const file = new File(['dummy content'], 'example.txt', { type: 'text/plain' });
      const validations = [
        { validation: () => false, errorMessage: 'Error message 1' },
        { validation: () => true, errorMessage: 'Error message 2' },
      ];
      const result = validateFile(file, validations);
      expect(result).toEqual(['Error message 1']);
    });

    it('should return an array with all error messages when all validations fail', () => {
      const file = new File(['dummy content'], 'example.txt', { type: 'text/plain' });
      const validations = [
        { validation: () => false, errorMessage: 'Error message 1' },
        { validation: () => false, errorMessage: 'Error message 2' },
      ];
      const result = validateFile(file, validations);
      expect(result).toEqual(['Error message 1', 'Error message 2']);
    });
  });
  describe('formatFileSize', () => {
    test.each`
      size          | fixedPoints | separator | expected
      ${0}          | ${1}        | ${'.'}    | ${'0B'}
      ${500}        | ${1}        | ${'.'}    | ${'500B'}
      ${1500}       | ${1}        | ${'.'}    | ${'1.5KB'}
      ${1000000}    | ${1}        | ${'.'}    | ${'1MB'}
      ${1000000}    | ${2}        | ${'.'}    | ${'1MB'}
      ${1500000}    | ${2}        | ${','}    | ${'1,5MB'}
      ${1000000000} | ${1}        | ${'.'}    | ${'1GB'}
      ${1500000000} | ${2}        | ${','}    | ${'1,5GB'}
    `(
      'returns $expected when size is $size, fixedPoints is $fixedPoints and separator is $separator',
      ({ size, fixedPoints, separator, expected }) => {
        const result = formatFileSize(size, { fixedPoints, separator });
        expect(result).toBe(expected);
      }
    );
  });
});
